//! Watches Explorer's XAML visual tree and hands the taskbar background elements to
//! [`background`]. XAML reports each island on its own UI thread, so state is per thread.
// Both lints fire inside the code generated by windows-core's `#[implement]`.
#![allow(clippy::ref_as_ptr, clippy::inline_always)]

use crate::guard::guard;
use crate::xamlom::{
    IVisualTreeService2, IVisualTreeServiceCallback_Impl, IVisualTreeServiceCallback2,
    IVisualTreeServiceCallback2_Impl, InstanceHandle, MUTATION_ADD, ParentChildRelation,
    VisualElement,
};
use crate::{background, control};
use hyaline_core::tap::{InitData, is_taskbar_background};
use std::cell::RefCell;
use std::collections::HashMap;
use windows_core::{HRESULT, Interface, PCWSTR, implement};

struct Node {
    name: String,
    parent: InstanceHandle,
}

thread_local! {
    static NODES: RefCell<HashMap<InstanceHandle, Node>> = RefCell::new(HashMap::new());
}

/// Moves the visual tree service to the thread that subscribes to it.
struct SendService(IVisualTreeService2);

// SAFETY: XAML Diagnostics requires `AdviseVisualTreeChange` to be called from a different
// thread than the one that delivered the site, so the service is meant to be handed over.
unsafe impl Send for SendService {}

impl SendService {
    fn into_inner(self) -> IVisualTreeService2 {
        self.0
    }
}

/// Subscribes to visual tree changes. Must not block: called from `SetSite`.
pub fn start(service: IVisualTreeService2, init: InitData) {
    let service = SendService(service);
    std::thread::spawn(move || {
        guard((), || {
            let service = service.into_inner();
            let callback: IVisualTreeServiceCallback2 = Callback {
                service: service.clone(),
                init,
            }
            .into();
            // SAFETY: `callback` is a valid COM object; the service keeps its own reference.
            let _ = unsafe { service.AdviseVisualTreeChange(callback.as_raw()) };
        });
    });
}

#[implement(IVisualTreeServiceCallback2)]
struct Callback {
    service: IVisualTreeService2,
    init: InitData,
}

impl Callback {
    fn on_change(&self, relation: &ParentChildRelation, element: &VisualElement, mutation: i32) {
        let handle = element.handle;
        if mutation != MUTATION_ADD {
            NODES.with_borrow_mut(|nodes| nodes.remove(&handle));
            background::forget(handle);
            return;
        }
        // SAFETY: XAML passes a valid NUL-terminated string (or null) for the callback's duration.
        let name = unsafe { wide_to_string(element.name) };
        let grandparent = NODES.with_borrow_mut(|nodes| {
            let grandparent = nodes
                .get(&relation.parent)
                .and_then(|parent| nodes.get(&parent.parent))
                .map(|node| node.name.clone());
            nodes.insert(
                handle,
                Node {
                    name: name.clone(),
                    parent: relation.parent,
                },
            );
            grandparent
        });
        if is_taskbar_background(&name, grandparent.as_deref()) {
            control::ensure(self.init);
            background::track(&self.service, handle);
        }
    }
}

impl IVisualTreeServiceCallback_Impl for Callback_Impl {
    unsafe fn OnVisualTreeChange(
        &self,
        relation: ParentChildRelation,
        element: VisualElement,
        mutation_type: i32,
    ) -> HRESULT {
        guard(HRESULT(0), || {
            self.on_change(&relation, &element, mutation_type);
            HRESULT(0)
        })
    }
}

impl IVisualTreeServiceCallback2_Impl for Callback_Impl {
    unsafe fn OnElementStateChanged(
        &self,
        _element: InstanceHandle,
        _state: i32,
        _context: PCWSTR,
    ) -> HRESULT {
        HRESULT(0)
    }
}

/// # Safety
/// `p` must be null or point to a NUL-terminated UTF-16 string.
unsafe fn wide_to_string(p: *const u16) -> String {
    if p.is_null() {
        return String::new();
    }
    // SAFETY: guaranteed by the caller.
    unsafe { PCWSTR(p).to_string() }.unwrap_or_default()
}
